import openpyxl, re
wb=openpyxl.load_workbook('/workspace/output.xlsx', data_only=False)
pat = re.compile(r"'(?P<sheet>[^']+)'!\$?(?P<col>[A-Z]{1,3})\$?(?P<row>[0-9]+)|(?<![A-Za-z$])\$?(?P<col2>[A-Z]{1,3})\$?(?P<row2>[0-9]+)")
for ws in wb.worksheets:
    flags=[]
    for row in ws.iter_rows():
        fs=[c for c in row if 6 <= c.column <= 15 and isinstance(c.value,str) and c.value.startswith('=') and not c.value.startswith('=TABLE')]
        if len(fs)<5: continue
        refs_by_cell=[]
        for c in fs:
            refs=[]
            for m in pat.finditer(c.value):
                sheet=m.group('sheet') if m.group('sheet') else ws.title
                r=int(m.group('row') or m.group('row2'))
                refs.append((sheet,r))
            refs_by_cell.append((c,refs))
        for sheet in set(s for _,refs in refs_by_cell for s,_ in refs):
            vals=[]
            for c,refs in refs_by_cell:
                rs=[r for s,r in refs if s==sheet]
                vals.append((c.coordinate, c.column, rs))
            maxlen=max(len(v[2]) for v in vals)
            for pos in range(maxlen):
                seq=[]
                for coord,col,rs in vals:
                    if pos < len(rs): seq.append((col,rs[pos],coord))
                if len(seq)<5: continue
                deltas=[]
                for i in range(len(seq)-1):
                    deltas.append(seq[i+1][1]-seq[i][1])
                majority=max(set(deltas), key=deltas.count) if deltas else None
                for i in range(len(seq)-1):
                    if seq[i][0]+1 != seq[i+1][0]: continue
                    d=seq[i+1][1]-seq[i][1]
                    if d != majority:
                        flags.append((ws.title, seq[i][2], seq[i+1][2], 'delta', d, 'expected', majority))
    if flags:
        print('\n==', ws.title, '==')
        for f in flags[:200]: print(f)
